UPDATE tc_model_param
   SET param_value = #{m.paramValue},
       description = #{m.description},
       updated_at  = CURRENT_TIMESTAMP
 WHERE model_version_key = #{m.modelVersionKey}
   AND param_name = #{m.paramName}

mapper.select:
SELECT 
  FROM tc_model_param
 WHERE model_version_key = #{modelVersionKey}
   AND param_name = #{paramName}

SELECT 
  FROM tc_model_param
 WHERE model_version_key = #{modelVersionKey}
 ORDER BY model_param_key ASC

    LIMIT #{limit} OFFSET #{offset}
